/* The kinds of each Native function's parameters (generated by tools/diffcheck.py), so the
 * check gives each a value of its type. */
#ifndef RUNTIME_NATIVE_PARAMS_H
#define RUNTIME_NATIVE_PARAMS_H

#include <stdint.h>

enum NativeParamKind {
    PARAM_WORD,
    PARAM_U8,
    PARAM_S8,
    PARAM_U16,
    PARAM_S16,
    PARAM_POINTER,
    PARAM_UNKNOWN = 7 /* a structure by value, a 64-bit value, or an unrecognised type */
};

typedef struct NativeParams {
    uint32_t address; /* DS address, bit 0 clear */
    uint32_t count;
    /* three bits per parameter, `this` first for a member function; bit 31 set when some are
     * unknown or there are more than ten */
    uint32_t kinds;
} NativeParams;

extern const NativeParams native_param_kinds[];
extern const uint32_t native_param_kinds_count;

/* Functions whose differences are explained in tests/native/known.txt (sorted). */
extern const uint32_t native_known[];
extern const uint32_t native_known_count;

#endif
